def traffic_light_probability(Tg, Ty, Tr, n, observations, tq, cq):
    cycle_time = Tg + Ty + Tr

    def time_to_color(t):
        cycle_start = t % cycle_time
        if cycle_start < Tg:
            return "green"
        elif cycle_start < Tg + Ty:
            return "yellow"
        else:
            return "red"

    observation_counts = {"green": 0, "yellow": 0, "red": 0}
    possible_starts = set()

    for t, color in observations:
        observation_counts[color] += 1
        cycle_start = t % cycle_time
        if color == "green":
            possible_starts.add(cycle_start)
        elif color == "yellow":
            possible_starts.add((cycle_start - Tg) % cycle_time)
        elif color == "red":
            possible_starts.add((cycle_start - Tg - Ty) % cycle_time)

    possible_cycle_starts = list(possible_starts)
    consistent_probabilities = []

    for start in possible_cycle_starts:
        if observation_counts[time_to_color(start)] > 0 and observation_counts[time_to_color(start + Tg)] > 0 and observation_counts[time_to_color(start + Tg + Ty)] > 0 and observation_counts[time_to_color(start + Tg + Ty + Tr)] > 0:
            consistent_probabilities.append(start)

    if not consistent_probabilities:
        return 0.0

    probability = 0.0
    for start in consistent_probabilities:
        time_in_cycle = (tq - start) % cycle_time
        if time_to_color(time_in_cycle) == cq:
            probability += 1

    return probability / len(consistent_probabilities)

