def calculate_probability(t_g, t_y, t_r, n, observations, t_q, c_q):
    # Calculate the total cycle time
    total_cycle_time = t_g + t_y + t_r

    # Determine possible starting times T based on observations
    possible_T = []

    for t, color in observations:
        # Calculate the start time T for this observation
        if color == 'green':
            T = t
        elif color == 'yellow':
            T = t - t_g
        elif color == 'red':
            T = t - t_g - t_y

        possible_T.append(T)

    # Find the minimum and maximum consistent T values
    min_T = min(possible_T)
    max_T = max(possible_T)

    # Normalize t_q to a cycle time within min_T to max_T
    def normalize_time(t):
        return (t - min_T) % total_cycle_time + min_T

    normalized_t_q = normalize_time(t_q)

    # Determine the cycle phase of t_q
    if min_T <= normalized_t_q < min_T + t_g:
        current_color = 'green'
    elif min_T + t_g <= normalized_t_q < min_T + t_g + t_y:
        current_color = 'yellow'
    else:
        current_color = 'red'

    # Calculate the probability
    if current_color == c_q:
        # If current_color matches c_q, count full cycles that include normalized_t_q
        full_cycles = (normalized_t_q - min_T) // total_cycle_time + 1
        return full_cycles / (max_T - min_T + total_cycle_time)
    else:
        return 0.0

