def calculate_probability(t_g, t_y, t_r, observations, t_q, c_q):
    total_cycle_time = t_g + t_y + t_r

    def get_color_at_time(t):
        if t % total_cycle_time < t_g:
            return 'green'
        elif t % total_cycle_time < t_g + t_y:
            return 'yellow'
        else:
            return 'red'

    # Determine possible T values
    possible_t = set()
    for t, c in observations:
        if c == get_color_at_time(t):
            possible_t.add(t % total_cycle_time)

    if not possible_t:
        return 0.0

    # Count occurrences of c_q in possible T contexts
    count_cq = 0
    for t in range(t_q, t_q + total_cycle_time):
        if t % total_cycle_time in possible_t and get_color_at_time(t) == c_q:
            count_cq += 1

    # Probability is count_cq divided by total_cycle_time
    probability = count_cq / total_cycle_time
    return probability

