def solve_traffic_light_probability():
    T_g, T_y, T_r = map(int, input().split())
    n = int(input())

    observations = []
    for _ in range(n):
        t, c = input().split()
        observations.append((int(t), c))

    t_q, c_q = input().split()
    t_q = int(t_q)

    total_time = sum(T_g, T_y, T_r)
    color_times = {'green': 0, 'yellow': 0, 'red': 0}

    for i in range(n):
        current_time = observations[i][0]
        current_color = observations[i][1]

        if i == 0:
            cycle_start = current_time - (current_time % total_time)
        else:
            prev_time = observations[i-1][0]
            cycle_start = prev_time - (prev_time % total_time)

        if current_time < cycle_start + T_g:
            color_times['green'] += min(current_time - (cycle_start if i == 0 else prev_time), T_g)
        elif current_time < cycle_start + T_g + T_y:
            color_times['yellow'] += min(current_time - (cycle_start + T_g), T_y)
        else:
            color_times['red'] += min(current_time - (cycle_start + T_g + T_y), T_r)

    total_observed_time = sum(color_times.values())

    for obs_time, obs_color in observations:
        cycle_start = obs_time - (obs_time % total_time)
        if obs_color == 'green':
            color_times['green'] += min(obs_time - (cycle_start + T_g + T_y), T_r)
        elif obs_color == 'yellow':
            color_times['yellow'] += min(obs_time - (cycle_start + T_g), T_g)
        else:  # red
            color_times['red'] += min(obs_time - cycle_start, T_g + T_y)

    if c_q == 'green':
        probability = color_times['green'] / total_observed_time
    elif c_q == 'yellow':
        probability = color_times['yellow'] / total_observed_time
    else:  # red
        probability = color_times['red'] / total_observed_time

    print(f"{probability:.6f}")

