def solve():
    Tg, Ty, Tr = map(int, input().split())
    n = int(input())
    observations = [tuple(input().split()) for _ in range(n)]
    tq, cq = input().split()
    tq = int(tq)

    def lcm(a, b):
        return a * b // gcd(a, b)

    def lcm_three(a, b, c):
        return lcm(lcm(a, b), c)

    cycle_length = lcm_three(Tg, Ty, Tr)

    if cq == 'green':
        color_start = 0
    elif cq == 'yellow':
        color_start = Tg
    else:  # red
        color_start = Tg + Ty

    color_end = (color_start + cycle_length) % cycle_length

    if color_start <= color_end:
        count = (color_end - color_start) // cycle_length + 1
    else:
        count = cycle_length - color_start + (cycle_length - color_end)

    prob = count / 3

    print(f"{prob:.3f}")

